// ─── File: src/main/java/com/bank/liveness/ConsumerLivenessDemo.java ───
package com.bank.liveness;

import java.util.logging.*;

public class ConsumerLivenessDemo {
    private static final Logger log = Logger.getLogger(ConsumerLivenessDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // session.timeout=45s, max.poll.interval=5m
        LivenessMonitor monitor = new LivenessMonitor(45_000, 300_000);

        // A: healthy — recent heartbeat, fast batch.
        logCase(monitor, "Healthy consumer",
            new LivenessSnapshot(1_000, 2_000));
        // B: CRASHED — no heartbeat for 60s (> session.timeout).
        logCase(monitor, "Crashed/unreachable consumer",
            new LivenessSnapshot(60_000, 0));
        // C: STALLED — heartbeats fine (2s) but batch stuck 6 min on compliance call.
        logCase(monitor, "Alive but stalled on slow compliance call",
            new LivenessSnapshot(2_000, 360_000));
    }

    private static void logCase(LivenessMonitor monitor, String label, LivenessSnapshot s) {
        LivenessMonitor.Verdict v = monitor.evaluate(s);
        if (v.evicted())
            log.warning(() -> label + " → EVICTED by " + v.trigger() + ": " + v.reason());
        else
            log.info(() -> label + " → healthy group member");
    }
}

