class LivenessSnapshot {
    private final long msSinceLastHeartbeat;   // background thread signal
    private final long msInCurrentBatch;        // application thread signal
    LivenessSnapshot(long msSinceLastHeartbeat, long msInCurrentBatch) {
        this.msSinceLastHeartbeat = msSinceLastHeartbeat;
        this.msInCurrentBatch = msInCurrentBatch;
    }
    long getMsSinceLastHeartbeat() { return msSinceLastHeartbeat; }
    long getMsInCurrentBatch() { return msInCurrentBatch; }
}

// ─── Would be in service/LivenessMonitor.java in a real project ───
class LivenessMonitor {
    private final long sessionTimeoutMs;
    private final long maxPollIntervalMs;
    LivenessMonitor(long sessionTimeoutMs, long maxPollIntervalMs) {
        this.sessionTimeoutMs = sessionTimeoutMs;
        this.maxPollIntervalMs = maxPollIntervalMs;
    }

    Verdict evaluate(LivenessSnapshot s) {
        // Mechanism 1 (heartbeat thread): no heartbeat within session.timeout → CRASH.
        if (s.getMsSinceLastHeartbeat() > sessionTimeoutMs)
            return Verdict.evicted("session.timeout.ms",
                "no heartbeat for " + s.getMsSinceLastHeartbeat() + "ms (process down/unreachable)");
        // Mechanism 2 (application thread): no poll() within interval → STALL,
        // fires EVEN THOUGH heartbeats are still flowing.
        if (s.getMsInCurrentBatch() > maxPollIntervalMs)
            return Verdict.evicted("max.poll.interval.ms",
                "no poll() for " + s.getMsInCurrentBatch()
                + "ms (handler stalled; heartbeats still OK)");
        return Verdict.alive();
    }

    static final class Verdict {
        private final boolean evicted;
        private final String trigger;
        private final String reason;
        private Verdict(boolean evicted, String trigger, String reason) {
                this.evicted = evicted;
                this.trigger = trigger
                this.reason = reason;
        }
        static Verdict alive() { return new Verdict(false, "", "ok"); }
        static Verdict evicted(String trigger, String reason) {
            return new Verdict(true, trigger, reason);
        }
        boolean evicted() { return evicted; }
        String trigger() { return trigger; }
        String reason() { return reason; }
    }
}

